/** Runtime configuration. Deployed builds read /config.json (written by CDK per environment),
 * so one build serves every environment. Local dev reads VITE_* variables from web/.env.local
 * (generated by scripts/write_web_env.py). */

export interface AppConfig {
  environment: string;
  region: string;
  userPoolId: string;
  userPoolClientId: string;
  apiUrl: string;
  agentRuntimeArn: string;
  /** Show the create-account screen. A UI hint only: Cognito decides whether sign-up works. */
  selfSignUp: boolean;
}

const REQUIRED: (keyof AppConfig)[] = [
  "region",
  "userPoolId",
  "userPoolClientId",
  "apiUrl",
  "agentRuntimeArn",
];

export function validateConfig(raw: unknown): AppConfig {
  if (!raw || typeof raw !== "object") throw new Error("config is not an object");
  const cfg = raw as Record<string, unknown>;
  for (const key of REQUIRED) {
    if (typeof cfg[key] !== "string" || !(cfg[key] as string).trim()) {
      throw new Error(`config is missing ${key}`);
    }
  }
  const apiUrl = String(cfg.apiUrl);
  if (!apiUrl.startsWith("https://")) throw new Error("apiUrl must be https");
  return {
    environment: typeof cfg.environment === "string" ? cfg.environment : "unknown",
    region: String(cfg.region),
    userPoolId: String(cfg.userPoolId),
    userPoolClientId: String(cfg.userPoolClientId),
    apiUrl: apiUrl.endsWith("/") ? apiUrl : `${apiUrl}/`,
    agentRuntimeArn: String(cfg.agentRuntimeArn),
    selfSignUp: cfg.selfSignUp === true || cfg.selfSignUp === "true",
  };
}

export async function loadConfig(): Promise<AppConfig> {
  if (import.meta.env.DEV) {
    const env = import.meta.env;
    return validateConfig({
      environment: env.VITE_ENVIRONMENT,
      region: env.VITE_REGION,
      userPoolId: env.VITE_USER_POOL_ID,
      userPoolClientId: env.VITE_USER_POOL_CLIENT_ID,
      apiUrl: env.VITE_API_URL,
      agentRuntimeArn: env.VITE_AGENT_RUNTIME_ARN,
      selfSignUp: env.VITE_SELF_SIGN_UP,
    });
  }
  const resp = await fetch("/config.json", { cache: "no-store" });
  if (!resp.ok) throw new Error(`could not load config (${resp.status})`);
  return validateConfig(await resp.json());
}
